#pragma once

// The artwork of the launcher: PNGs embedded in the exe (launcher.rc.in,
// RCDATA) and uploaded to the D3D11 device through WIC. Every image is
// generated by tools/launcher/artwork/gen_art.py - original art, no game
// assets - so a distributed copy is self-contained and carries nothing from
// the game's data.

#include <d3d11.h>

#include <string>

namespace Launcher {

// Resource ids, mirrored by launcher.rc.in.
enum ArtworkResource : int {
    kArtPlay = 101,     // hero_play.png       - Play page hero
    kArtGameData = 102, // banner_gamedata.png - Game Data page banner
    kArtUpdates = 103,  // banner_updates.png  - Updates page banner
    kArtPlayer = 104,   // banner_player.png   - Player page banner
    kArtOnline = 105,   // banner_online.png   - Online page banner
    kArtBanner = 106,   // banner_sidebar.png  - the sidebar's top banner
};

struct ArtworkImage {
    ID3D11ShaderResourceView *View = nullptr;
    int Width = 0;
    int Height = 0;
    bool IsValid() const { return View != nullptr; }
    void Release();
};

struct Artwork {
    ArtworkImage Play;
    ArtworkImage GameData;
    ArtworkImage Updates;
    ArtworkImage Player;
    ArtworkImage Online;
    ArtworkImage Banner;
    std::string Error;

    ArtworkImage &ForResource( int resourceId );
    void Release();
};

bool LoadArtwork( ID3D11Device *device, Artwork &artwork );

} // namespace Launcher
